","edit_kind":"declaration","corrected_code":"package org.fedorahosted.freeotp.encryptor;

import android.content.Context;
import android.content.SharedPreferences;
import android.security.keystore.KeyGenParameterSpec;
import android.security.keystore.KeyProperties;
import android.security.keystore.KeyProtection;
import android.util.Log;

import com.google.gson.Gson;

import org.fedorahosted.freeotp.Token;

import java.io.IOException;
import java.security.GeneralSecurityException;
import java.security.InvalidAlgorithmParameterException;
import java.security.InvalidKeyException;
import java.security.Key;
import java.security.KeyStore;
import java.security.KeyStoreException;
import java.security.NoSuchAlgorithmException;
import java.security.UnrecoverableKeyException;
import java.security.cert.CertificateException;
import java.util.HashMap;
import java.util.Map;

import javax.crypto.BadPaddingException;
import javax.crypto.IllegalBlockSizeException;
import javax.crypto.KeyGenerator;
import javax.crypto.NoSuchPaddingException;
import javax.crypto.SecretKey;
import javax.crypto.spec.SecretKeySpec;

public class Encryptor {
    private static final String LOGTAG = "Encryptor";

    private static final String MASTER = "masterKey";
    private static final String CURRENT_MASTER = "currentMasterKey";
    private KeyStore mKeyStore;

    public Encryptor(Context ctx) throws KeyStoreException, CertificateException,
            NoSuchAlgorithmException, IOException {
        mKeyStore = KeyStore.getInstance("AndroidKeyStore");
        mKeyStore.load(null);
    }

    public Map<String, EncryptedKey> encryptToken(SecretKey key) throws
            NoSuchAlgorithmException, IllegalBlockSizeException, InvalidKeyException,
            BadPaddingException, NoSuchPaddingException, IOException {
        Map<String, EncryptedKey> data = new HashMap<>();

        SecretKey currentMasterKey = getCurrentWrappingKey();

        // Encrypt token key
        EncryptedKey ekc = EncryptedKey.encrypt(currentMasterKey, key, CURRENT_MASTER);

        data.put("key", ekc);
        return data;
    }

    private SecretKey getLegacyWrappingKey() {
        try {
            return (SecretKey) mKeyStore.getKey(MASTER, null);
        } catch (Exception e) {
            Log.e(LOGTAG, "Exception", e);
            return null;
        }
    }

    private synchronized SecretKey getCurrentWrappingKey() throws
            NoSuchAlgorithmException, InvalidKeyException, IOException {
        try {
            Key existingKey = mKeyStore.getKey(CURRENT_MASTER, null);
            if (existingKey != null) {
                if (existingKey instanceof SecretKey) {
                    return (SecretKey) existingKey;
                }
                throw new InvalidKeyException("AndroidKeyStore entry is not a secret key");
            }

            KeyGenerator keyGenerator = KeyGenerator.getInstance(
                    KeyProperties.KEY_ALGORITHM_AES, mKeyStore.getProvider());
            keyGenerator.init(new KeyGenParameterSpec.Builder(
                    CURRENT_MASTER,
                    KeyProperties.PURPOSE_ENCRYPT | KeyProperties.PURPOSE_DECRYPT)
                    .setBlockModes(KeyProperties.BLOCK_MODE_GCM)
                    .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE)
                    .setRandomizedEncryptionRequired(true)
                    .build());
            return keyGenerator.generateKey();
        } catch (InvalidAlgorithmParameterException e) {
            throw new InvalidKeyException("Unable to configure current wrapping key", e);
        } catch (KeyStoreException | UnrecoverableKeyException e) {
            throw new IOException("Unable to resolve current wrapping key", e);
        }
    }
}
